package com.twitchsidepanel;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("twitchsidepanel")
public interface TwitchSidePanelConfig extends Config
{
	@ConfigItem(
		keyName = "channel",
		name = "Twitch channel",
		description = "Enter the Twitch channel name or URL you want to connect to.",
		position = 1
	)
	default String channel()
	{
		return "";
	}

	@ConfigItem(
		keyName = "autoConnect",
		name = "Auto-connect on login",
		description = "Connect automatically when the client starts.",
		position = 2
	)
	default boolean autoConnect()
	{
		return false;
	}

	@ConfigItem(
		keyName = "colorUsernames",
		name = "Color usernames",
		description = "Show each chatter's name in their Twitch color.",
		position = 3
	)
	default boolean colorUsernames()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTimestamps",
		name = "Show timestamps",
		description = "Show the time each message arrived.",
		position = 4
	)
	default boolean showTimestamps()
	{
		return true;
	}

	@ConfigItem(
		keyName = "maxMessages",
		name = "Message history",
		description = "How many messages to keep before older ones scroll off.",
		position = 5
	)
	default int maxMessages()
	{
		return 200;
	}

	@ConfigItem(
		keyName = "textSize",
		name = "Text size",
		description = "Size of incoming chat message text.",
		position = 6
	)
	default TextSize textSize()
	{
		return TextSize.MEDIUM;
	}

	enum TextSize
	{
		SMALL,
		MEDIUM,
		LARGE;

		public float points()
		{
			switch (this)
			{
				case SMALL:
					return 12f;
				case LARGE:
					return 16f;
				default:
					return 14f;
			}
		}

		@Override
		public String toString()
		{
			switch (this)
			{
				case SMALL:
					return "Small";
				case LARGE:
					return "Large";
				default:
					return "Medium";
			}
		}
	}

	// --- Internal state below, not shown in the settings UI. Written directly via
	// ConfigManager.setConfiguration() rather than through this interface. ---

	@ConfigItem(keyName = "accessToken", name = "", description = "", hidden = true)
	default String accessToken()
	{
		return "";
	}

	@ConfigItem(keyName = "loggedInUsername", name = "", description = "", hidden = true)
	default String loggedInUsername()
	{
		return "";
	}
}

package com.twitchsidepanel;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.twitchsidepanel.twitch.BadgeIconCache;
import com.twitchsidepanel.twitch.TwitchAuthService;
import com.twitchsidepanel.twitch.TwitchChannelName;
import com.twitchsidepanel.twitch.TwitchChatClient;
import com.twitchsidepanel.twitch.TwitchChatListener;
import com.twitchsidepanel.twitch.TwitchMessage;
import com.twitchsidepanel.twitch.TwitchSubEvent;
import com.twitchsidepanel.ui.TwitchPanelIcon;
import com.twitchsidepanel.ui.TwitchSidePanel;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.ImageIcon;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

/**
 * Shows Twitch chat in a RuneLite side panel, Party-Hub style, instead of the official
 * Twitch plugin's chatbox-PM format.
 * <p>
 * Only ever connects to the single channel set in this plugin's config - there's no
 * in-panel way to switch to a different channel at runtime. Reading chat works
 * anonymously with no login; logging in with Twitch (device code flow) additionally
 * unlocks sending messages as yourself.
 */
@PluginDescriptor(
	name = "Twitch Chat Side Panel",
	description = "Shows your Twitch channel's chat in a side panel instead of the chatbox PM format",
	tags = {"twitch", "chat", "stream", "panel"}
)
public class TwitchSidePanelPlugin extends Plugin implements TwitchChatListener
{
	private static final String CONFIG_GROUP = "twitchsidepanel";

	// One shared Client ID for everyone using this plugin - it just identifies "which app
	// is asking" to Twitch and isn't secret (that's the whole point of the "Public"
	// client type), unlike a client secret. Each user still logs in with their own
	// account and gets their own token; nothing is shared between users except this ID.
	private static final String CLIENT_ID = "azsobegarjzbpgosk97ydc9g64j6ou";

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private TwitchSidePanelConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private ScheduledExecutorService executor;

	private TwitchSidePanel panel;
	private NavigationButton navButton;
	private TwitchChatClient chatClient;
	private final BadgeIconCache badgeIconCache = new BadgeIconCache();
	private TwitchAuthService authService;

	// Twitch's chat gateway NAKs the IRCv3 "echo-message" capability (confirmed live),
	// so a message you send is never echoed back over IRC - selfColor/selfBadges (from
	// the USERSTATE Twitch sends on an authenticated connection) let a locally-echoed
	// copy of a sent message look the same as if it had arrived from the server.
	private volatile Color selfColor;
	private volatile List<TwitchMessage.BadgeRef> selfBadges = Collections.emptyList();

	@Provides
	TwitchSidePanelConfig getConfig(final ConfigManager configManager)
	{
		return configManager.getConfig(TwitchSidePanelConfig.class);
	}

	@Override
	protected void startUp()
	{
		authService = new TwitchAuthService(gson, executor);
		chatClient = new TwitchChatClient(this);

		panel = new TwitchSidePanel(new TwitchSidePanel.Handlers()
		{
			@Override
			public void onConnectClicked()
			{
				connectToChannel();
			}

			@Override
			public void onDisconnectClicked()
			{
				chatClient.disconnect();
				panel.setConnected(false);
				panel.setStatus("Not connected", false);
			}

			@Override
			public void onLoginClicked()
			{
				startLogin();
			}

			@Override
			public void onCancelLoginClicked()
			{
				authService.cancel();
			}

			@Override
			public void onLogoutClicked()
			{
				clearLogin();
				panel.showLoginPrompt();
			}

			@Override
			public void onSendMessage(String text)
			{
				chatClient.sendMessage(text);
				echoSentMessageLocally(text);
			}
		}, TwitchChannelName.normalize(config.channel()));

		BufferedImage icon = TwitchPanelIcon.create();

		navButton = NavigationButton.builder()
			.tooltip("Twitch Chat")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);

		restoreLoginState();

		if (config.autoConnect() && !TwitchChannelName.normalize(config.channel()).isEmpty())
		{
			connectToChannel();
		}
	}

	@Override
	protected void shutDown()
	{
		authService.cancel();
		if (chatClient != null)
		{
			chatClient.disconnect();
		}
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
		panel = null;
	}

	private void connectToChannel()
	{
		String channel = TwitchChannelName.normalize(config.channel());
		panel.setStatus("Connecting to #" + channel + "...", false);

		String accessToken = config.accessToken();
		String username = config.loggedInUsername();
		if (!accessToken.isEmpty() && !username.isEmpty())
		{
			chatClient.connectAuthenticated(channel, username, accessToken);
		}
		else
		{
			chatClient.connect(channel);
		}
	}

	private void startLogin()
	{
		authService.startLogin(CLIENT_ID, new TwitchAuthService.LoginListener()
		{
			@Override
			public void onCodeReady(String userCode, String verificationUri)
			{
				if (panel != null)
				{
					panel.showDeviceCode(userCode, verificationUri);
				}
			}

			@Override
			public void onAuthorized(String accessToken, String username)
			{
				configManager.setConfiguration(CONFIG_GROUP, "accessToken", accessToken);
				configManager.setConfiguration(CONFIG_GROUP, "loggedInUsername", username);
				if (panel != null)
				{
					panel.showLoggedIn(username);
				}
				loadBadgeIcons(accessToken);
			}

			@Override
			public void onError(String message)
			{
				if (panel != null)
				{
					panel.showLoginError(message);
				}
			}
		});
	}

	private void restoreLoginState()
	{
		String accessToken = config.accessToken();
		if (accessToken.isEmpty())
		{
			panel.showLoginPrompt();
			return;
		}

		// Validating blocks on a network call - run it off the startUp() thread so
		// plugin startup itself never stalls waiting on Twitch.
		executor.execute(() ->
		{
			String username = authService.validateToken(accessToken);
			if (panel == null)
			{
				return;
			}
			if (username != null)
			{
				configManager.setConfiguration(CONFIG_GROUP, "loggedInUsername", username);
				panel.showLoggedIn(username);
				loadBadgeIcons(accessToken);
			}
			else
			{
				clearLogin();
				panel.showLoginPrompt();
			}
		});
	}

	private void loadBadgeIcons(String accessToken)
	{
		String channel = TwitchChannelName.normalize(config.channel());
		if (channel.isEmpty())
		{
			return;
		}
		executor.execute(() -> badgeIconCache.loadForChannel(CLIENT_ID, accessToken, channel));
	}

	private void clearLogin()
	{
		configManager.unsetConfiguration(CONFIG_GROUP, "accessToken");
		configManager.unsetConfiguration(CONFIG_GROUP, "loggedInUsername");
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()) || !"channel".equals(event.getKey()))
		{
			return;
		}

		String raw = config.channel();
		String normalized = TwitchChannelName.normalize(raw);
		if (!normalized.equals(raw))
		{
			// Rewriting the stored value (rather than only normalizing at the call
			// sites that actually connect) means the settings field itself shows the
			// cleaned-up channel name - visible confirmation that pasting a channel
			// URL worked, not just silent under-the-hood handling. This re-fires
			// onConfigChanged with the already-normalized value, which then falls
			// through to the branch below and stops.
			configManager.setConfiguration(CONFIG_GROUP, "channel", normalized);
			return;
		}

		if (panel != null)
		{
			panel.setChannel(normalized);
		}
	}

	@Override
	public void onConnected(String channel)
	{
		if (panel == null)
		{
			return;
		}
		panel.setConnected(true);
		panel.setStatus("Connected to #" + channel, false);
		panel.appendSystemMessage("Connected to #" + channel);
	}

	@Override
	public void onDisconnected(String reason)
	{
		if (panel == null)
		{
			return;
		}
		panel.setConnected(false);
		panel.setStatus(reason, true);
	}

	@Override
	public void onMessage(TwitchMessage message)
	{
		renderMessage(message);
	}

	@Override
	public void onSelfUserState(Color color, List<TwitchMessage.BadgeRef> badges)
	{
		selfColor = color;
		selfBadges = badges;
	}

	@Override
	public void onSubEvent(TwitchSubEvent event)
	{
		if (panel != null)
		{
			panel.addSubEvent(event);
		}
	}

	/**
	 * Renders a message you just sent yourself, since Twitch never echoes it back over
	 * IRC (see the NAK note near {@link #selfColor}). Runs the icon lookups on a
	 * background thread, same as a normal incoming message, so a cache-miss network
	 * fetch never blocks the button click that triggered this.
	 */
	private void echoSentMessageLocally(String text)
	{
		String username = config.loggedInUsername();
		if (username.isEmpty())
		{
			return;
		}

		executor.execute(() ->
			renderMessage(new TwitchMessage(username, text, selfColor, System.currentTimeMillis(), selfBadges)));
	}

	/**
	 * Resolves badge icons (blocking on a network fetch for any not already cached) and
	 * hands the message off to the panel to render. Must be called from a background
	 * thread, never the Swing EDT - {@code onMessage} already runs on the WebSocket
	 * listener's thread, and {@link #echoSentMessageLocally} hops onto one.
	 */
	private void renderMessage(TwitchMessage message)
	{
		if (panel == null)
		{
			return;
		}

		Map<String, ImageIcon> badgeIcons = new HashMap<>();
		for (TwitchMessage.BadgeRef badge : message.badges)
		{
			String key = badge.setId + "/" + badge.version;
			if (!badgeIcons.containsKey(key))
			{
				ImageIcon icon = badgeIconCache.get(badge.setId, badge.version);
				if (icon != null)
				{
					badgeIcons.put(key, icon);
				}
			}
		}

		panel.appendMessage(message, config.colorUsernames(), config.showTimestamps(), config.maxMessages(),
			config.textSize().points(), badgeIcons);
	}
}

package com.twitchsidepanel.twitch;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.imageio.ImageIO;
import javax.swing.ImageIcon;

/**
 * Fetches and caches Twitch chat badge icons (moderator, subscriber, vip, etc.) for a
 * channel. Needs an authenticated Helix API call (Client ID + user OAuth token) - so badge
 * icons only render once the user has logged in. Badge *names* still arrive over IRC even
 * for anonymous connections; this only concerns fetching the icon images to go with them.
 */
public class BadgeIconCache
{
	private static final int TARGET_HEIGHT = 18;
	private static final Duration TIMEOUT = Duration.ofSeconds(10);

	private final HttpClient httpClient = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
	private final Map<String, String> iconUrlsBySetVersion = new ConcurrentHashMap<>();
	private final Map<String, ImageIcon> iconCache = new ConcurrentHashMap<>();

	/**
	 * Fetches the global and channel-specific badge sets for {@code channel} and remembers
	 * their icon URLs (the actual images are still fetched lazily, on first use, via
	 * {@link #get}). Blocks on several network calls - call from a background thread, and
	 * expect it to silently do nothing if the token/client ID turn out to be invalid,
	 * since a missing badge icon just falls back to no icon rather than breaking chat.
	 */
	public void loadForChannel(String clientId, String accessToken, String channel)
	{
		try
		{
			String broadcasterId = fetchBroadcasterId(clientId, accessToken, channel);

			loadBadgeSets(clientId, accessToken, "https://api.twitch.tv/helix/chat/badges/global");
			if (broadcasterId != null)
			{
				loadBadgeSets(clientId, accessToken,
					"https://api.twitch.tv/helix/chat/badges?broadcaster_id=" + broadcasterId);
			}
		}
		catch (IOException | InterruptedException | RuntimeException e)
		{
			// Badge icons are a nice-to-have on top of a working chat feed - a failure
			// here (bad token, bad client ID, network hiccup) should never take chat
			// down with it. Messages simply render without badge icons.
		}
	}

	/**
	 * Returns the cached/fetched icon for this badge set+version, or {@code null} if it's
	 * not known (never loaded, or failed to load). Blocks on a network fetch the first
	 * time a given badge is seen - call from a background thread, never the Swing EDT.
	 */
	public ImageIcon get(String setId, String version)
	{
		String key = setId + "/" + version;
		ImageIcon cached = iconCache.get(key);
		if (cached != null)
		{
			return cached;
		}

		String url = iconUrlsBySetVersion.get(key);
		if (url == null)
		{
			return null;
		}

		try
		{
			try (InputStream in = URI.create(url).toURL().openStream())
			{
				BufferedImage image = ImageIO.read(in);
				if (image == null)
				{
					return null;
				}
				int scaledWidth = Math.max(1, Math.round(image.getWidth() * (TARGET_HEIGHT / (float) image.getHeight())));
				Image scaled = image.getScaledInstance(scaledWidth, TARGET_HEIGHT, Image.SCALE_SMOOTH);
				ImageIcon icon = new ImageIcon(scaled);
				iconCache.put(key, icon);
				return icon;
			}
		}
		catch (IOException e)
		{
			return null;
		}
	}

	private String fetchBroadcasterId(String clientId, String accessToken, String channel)
		throws IOException, InterruptedException
	{
		HttpResponse<String> response = get(clientId, accessToken,
			"https://api.twitch.tv/helix/users?login=" + channel);
		if (response.statusCode() != 200)
		{
			return null;
		}
		JsonObject json = new JsonParser().parse(response.body()).getAsJsonObject();
		JsonArray data = json.getAsJsonArray("data");
		if (data == null || data.size() == 0)
		{
			return null;
		}
		return data.get(0).getAsJsonObject().get("id").getAsString();
	}

	private void loadBadgeSets(String clientId, String accessToken, String url) throws IOException, InterruptedException
	{
		HttpResponse<String> response = get(clientId, accessToken, url);
		if (response.statusCode() != 200)
		{
			return;
		}

		JsonObject json = new JsonParser().parse(response.body()).getAsJsonObject();
		JsonArray sets = json.getAsJsonArray("data");
		if (sets == null)
		{
			return;
		}

		for (int i = 0; i < sets.size(); i++)
		{
			JsonObject set = sets.get(i).getAsJsonObject();
			String setId = set.get("set_id").getAsString();
			JsonArray versions = set.getAsJsonArray("versions");
			if (versions == null)
			{
				continue;
			}
			for (int v = 0; v < versions.size(); v++)
			{
				JsonObject version = versions.get(v).getAsJsonObject();
				String versionId = version.get("id").getAsString();
				String imageUrl = version.get("image_url_1x").getAsString();
				iconUrlsBySetVersion.put(setId + "/" + versionId, imageUrl);
			}
		}
	}

	private HttpResponse<String> get(String clientId, String accessToken, String url)
		throws IOException, InterruptedException
	{
		HttpRequest request = HttpRequest.newBuilder(URI.create(url))
			.header("Client-Id", clientId)
			.header("Authorization", "Bearer " + accessToken)
			.GET()
			.build();
		return httpClient.send(request, HttpResponse.BodyHandlers.ofString());
	}
}

package com.twitchsidepanel.twitch;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.awt.Desktop;
import java.io.IOException;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Logs into Twitch using the OAuth 2.0 Device Code Grant flow - the user is shown a short
 * code and a URL, enters it on any device in a browser, and this polls Twitch until it's
 * approved. Chosen over the more common Authorization Code / Implicit flows because those
 * both need either a client secret (server-side apps only) or a localhost redirect
 * listener; device flow needs neither, which suits a desktop client with no backend.
 * <p>
 * Requests {@code chat:read chat:edit} scope - read/send chat as the logged in user.
 */
public class TwitchAuthService
{
	private static final String DEVICE_CODE_URL = "https://id.twitch.tv/oauth2/device";
	private static final String TOKEN_URL = "https://id.twitch.tv/oauth2/token";
	private static final String VALIDATE_URL = "https://id.twitch.tv/oauth2/validate";
	private static final String SCOPES = "chat:read chat:edit";

	private final HttpClient httpClient = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final AtomicBoolean cancelled = new AtomicBoolean(false);

	public TwitchAuthService(Gson gson, ScheduledExecutorService executor)
	{
		this.gson = gson;
		this.executor = executor;
	}

	public interface LoginListener
	{
		/**
		 * The user needs to visit {@code verificationUri} and enter {@code userCode}.
		 * Called once per login attempt, before any polling begins.
		 */
		void onCodeReady(String userCode, String verificationUri);

		void onAuthorized(String accessToken, String username);

		/**
		 * Login failed, expired, or was rejected - never called after {@link #cancel()}.
		 */
		void onError(String message);
	}

	/**
	 * Starts a login attempt on the client's shared executor. Only one attempt should be
	 * in flight at a time - call {@link #cancel()} first if a previous attempt is still
	 * polling.
	 */
	public void startLogin(String clientId, LoginListener listener)
	{
		cancelled.set(false);
		executor.execute(() -> runLogin(clientId, listener));
	}

	public void cancel()
	{
		cancelled.set(true);
	}

	private void runLogin(String clientId, LoginListener listener)
	{
		try
		{
			HttpResponse<String> deviceResponse = post(DEVICE_CODE_URL,
				"client_id=" + urlEncode(clientId) + "&scopes=" + urlEncode(SCOPES));

			if (deviceResponse.statusCode() != 200)
			{
				listener.onError("Twitch rejected the login request (HTTP " + deviceResponse.statusCode()
					+ "). Double check your Client ID.");
				return;
			}

			JsonObject device = gson.fromJson(deviceResponse.body(), JsonObject.class);
			String deviceCode = device.get("device_code").getAsString();
			String userCode = device.get("user_code").getAsString();
			String verificationUri = device.get("verification_uri").getAsString();
			int expiresInSeconds = device.get("expires_in").getAsInt();
			int intervalSeconds = device.has("interval") ? device.get("interval").getAsInt() : 5;

			listener.onCodeReady(userCode, verificationUri);
			openInBrowser(verificationUri);

			long deadline = System.currentTimeMillis() + expiresInSeconds * 1000L;
			schedulePoll(clientId, deviceCode, deadline, intervalSeconds, listener, intervalSeconds);
		}
		catch (Exception e)
		{
			// Deliberately broad: this runs on the executor with no uncaught-exception
			// handler, so anything narrower risks the task dying silently on a response
			// shaped differently than expected - "nothing happens" when you click the
			// button, with no error and nothing to debug.
			if (!cancelled.get())
			{
				listener.onError("Login error: " + (e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName()));
			}
		}
	}

	/**
	 * Best-effort convenience so the user doesn't have to copy the URL themselves - if
	 * this fails (unsupported platform/desktop environment) they can still use the code
	 * and link shown in the panel.
	 */
	private void openInBrowser(String uri)
	{
		try
		{
			if (Desktop.isDesktopSupported() && Desktop.getDesktop().isSupported(Desktop.Action.BROWSE))
			{
				Desktop.getDesktop().browse(URI.create(uri));
			}
		}
		catch (Exception ignored)
		{
			// Not fatal - the panel still shows the code and link to open manually.
		}
	}

	/**
	 * Schedules the next poll attempt {@code delaySeconds} from now on the client's shared
	 * executor, rather than blocking a thread on {@code Thread.sleep} between attempts.
	 */
	private void schedulePoll(String clientId, String deviceCode, long deadlineMillis, int intervalSeconds,
		LoginListener listener, int delaySeconds)
	{
		executor.schedule(() -> pollForToken(clientId, deviceCode, deadlineMillis, intervalSeconds, listener),
			delaySeconds, TimeUnit.SECONDS);
	}

	private void pollForToken(String clientId, String deviceCode, long deadlineMillis, int intervalSeconds,
		LoginListener listener)
	{
		if (cancelled.get())
		{
			return;
		}
		if (System.currentTimeMillis() >= deadlineMillis)
		{
			listener.onError("Login code expired - try again");
			return;
		}

		try
		{
			HttpResponse<String> tokenResponse = post(TOKEN_URL,
				"client_id=" + urlEncode(clientId)
					+ "&device_code=" + urlEncode(deviceCode)
					+ "&grant_type=" + urlEncode("urn:ietf:params:oauth:grant-type:device_code"));

			if (tokenResponse.statusCode() == 200)
			{
				JsonObject token = gson.fromJson(tokenResponse.body(), JsonObject.class);
				String accessToken = token.get("access_token").getAsString();
				String username = validateToken(accessToken);
				if (username == null)
				{
					listener.onError("Logged in, but couldn't verify the account - try again");
					return;
				}
				listener.onAuthorized(accessToken, username);
				return;
			}

			String message = safeMessage(tokenResponse.body());
			if ("authorization_pending".equals(message))
			{
				schedulePoll(clientId, deviceCode, deadlineMillis, intervalSeconds, listener, intervalSeconds);
				return;
			}
			if ("slow_down".equals(message))
			{
				int slowerInterval = intervalSeconds + 5;
				schedulePoll(clientId, deviceCode, deadlineMillis, slowerInterval, listener, slowerInterval);
				return;
			}

			listener.onError("Login failed: " + (message.isEmpty() ? ("HTTP " + tokenResponse.statusCode()) : message));
		}
		catch (Exception e)
		{
			// Same broad-catch reasoning as runLogin() - this callback has no other
			// safety net, so an unexpected failure should surface a visible error rather
			// than silently stop polling.
			if (!cancelled.get())
			{
				listener.onError("Login error: " + (e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName()));
			}
		}
	}

	/**
	 * Validates an access token (freshly issued, or one restored from a previous
	 * session) and returns the logged-in Twitch username, or {@code null} if it's
	 * invalid/expired.
	 */
	public String validateToken(String accessToken)
	{
		try
		{
			HttpRequest request = HttpRequest.newBuilder(URI.create(VALIDATE_URL))
				.header("Authorization", "OAuth " + accessToken)
				.GET()
				.build();
			HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
			if (response.statusCode() != 200)
			{
				return null;
			}
			JsonObject json = gson.fromJson(response.body(), JsonObject.class);
			return json.has("login") ? json.get("login").getAsString() : null;
		}
		catch (Exception e)
		{
			// Broad on purpose - callers run this on background threads with no outer
			// safety net, so an unexpected response shape should fall back to "not
			// logged in" rather than kill the thread silently.
			return null;
		}
	}

	private HttpResponse<String> post(String url, String form) throws IOException, InterruptedException
	{
		HttpRequest request = HttpRequest.newBuilder(URI.create(url))
			.header("Content-Type", "application/x-www-form-urlencoded")
			.POST(HttpRequest.BodyPublishers.ofString(form))
			.build();
		return httpClient.send(request, HttpResponse.BodyHandlers.ofString());
	}

	private String safeMessage(String body)
	{
		try
		{
			JsonObject json = gson.fromJson(body, JsonObject.class);
			return json != null && json.has("message") ? json.get("message").getAsString() : "";
		}
		catch (RuntimeException e)
		{
			return "";
		}
	}

	private static String urlEncode(String value)
	{
		return URLEncoder.encode(value, StandardCharsets.UTF_8);
	}
}

package com.twitchsidepanel.twitch;

import java.util.Locale;

/**
 * Normalizes whatever gets typed or pasted into the "Twitch channel" config field into a
 * plain channel name - so pasting a full channel URL straight from a browser's address bar
 * (e.g. {@code https://www.twitch.tv/somechannel} or {@code twitch.tv/somechannel/videos})
 * works exactly the same as typing the name itself.
 */
public final class TwitchChannelName
{
	private TwitchChannelName()
	{
	}

	public static String normalize(String raw)
	{
		if (raw == null)
		{
			return "";
		}

		String value = raw.trim();
		if (value.isEmpty())
		{
			return "";
		}

		// Strip a leading "@" or "#" (out of habit from other platforms, or a plain
		// "#channel" someone pasted) before URL handling below - a real URL never starts
		// with either, so this is unambiguous.
		while (value.startsWith("@") || value.startsWith("#"))
		{
			value = value.substring(1);
		}

		int twitchTv = value.toLowerCase(Locale.ROOT).indexOf("twitch.tv/");
		if (twitchTv >= 0)
		{
			value = value.substring(twitchTv + "twitch.tv/".length());
		}

		// Drop any path/query/fragment after the channel name itself, e.g. the
		// "/videos" in ".../somechannel/videos" or a "?foo=bar" some share links add.
		value = value.split("[/?#]", 2)[0];

		return value.trim();
	}
}

package com.twitchsidepanel.twitch;

import java.awt.Color;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.WebSocket;
import java.security.SecureRandom;
import java.time.Duration;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletionStage;

/**
 * Twitch IRC client, over WebSocket rather than raw IRC sockets so it still works on
 * networks that only allow outbound HTTPS (hotel wifi, corporate proxies, etc).
 * <p>
 * Without a login (see {@link #connect(String)}), this connects anonymously using a
 * "justinfan" throwaway nick - Twitch allows this for read-only access, but a message
 * can never be sent on such a connection. With a login (see
 * {@link #connectAuthenticated(String, String, String)}), it authenticates as the real
 * account so {@link #sendMessage(String)} can post to chat.
 * <p>
 * Either way it requests the IRCv3 "tags" capability so each message carries the
 * sender's chosen display name, name color, and badges.
 */
public class TwitchChatClient
{
	private static final URI ENDPOINT = URI.create("wss://irc-ws.chat.twitch.tv:443");
	private static final Duration CONNECT_TIMEOUT = Duration.ofSeconds(10);

	private final TwitchChatListener listener;
	private final HttpClient httpClient = HttpClient.newBuilder()
		.connectTimeout(CONNECT_TIMEOUT)
		.build();

	private volatile WebSocket webSocket;
	private volatile boolean stopRequested;
	private volatile String currentChannel;

	public TwitchChatClient(TwitchChatListener listener)
	{
		this.listener = listener;
	}

	/**
	 * Connects anonymously (read-only) and joins the given channel. Safe to call from the
	 * Swing EDT. {@code channel} may be typed with or without a leading '#' and in any case.
	 */
	public void connect(String channel)
	{
		doConnect(channel, null, null);
	}

	/**
	 * Connects authenticated as {@code nick} using an OAuth access token (chat:read
	 * chat:edit scopes), enabling {@link #sendMessage(String)} on this connection.
	 */
	public void connectAuthenticated(String channel, String nick, String oauthAccessToken)
	{
		doConnect(channel, nick, oauthAccessToken);
	}

	private void doConnect(String channel, String nick, String oauthAccessToken)
	{
		String normalizedChannel = normalizeChannel(channel);
		currentChannel = normalizedChannel;
		stopRequested = false;

		httpClient.newWebSocketBuilder()
			.connectTimeout(CONNECT_TIMEOUT)
			.buildAsync(ENDPOINT, new IrcListener(normalizedChannel, nick, oauthAccessToken))
			.exceptionally(error ->
			{
				if (!stopRequested)
				{
					listener.onDisconnected("Connection error: " + rootMessage(error));
				}
				return null;
			});
	}

	/**
	 * Sends a chat message to the currently connected channel. No-op if not connected on
	 * an authenticated connection. Never called automatically by this plugin - only in
	 * direct response to the user typing a message and pressing send.
	 */
	public void sendMessage(String text)
	{
		WebSocket ws = webSocket;
		String channel = currentChannel;
		if (ws == null || channel == null || text == null || text.trim().isEmpty())
		{
			return;
		}
		ws.sendText("PRIVMSG #" + channel + " :" + text.trim(), true);
	}

	public void disconnect()
	{
		stopRequested = true;
		WebSocket ws = webSocket;
		webSocket = null;
		if (ws != null)
		{
			// sendClose() only starts a graceful close handshake - the connection (and
			// incoming messages with it) doesn't actually stop until Twitch acks its own
			// close frame back, which isn't guaranteed to happen promptly. abort() tears
			// down the underlying TCP connection immediately, which is what a user
			// clicking "Disconnect" actually expects.
			ws.abort();
		}
	}

	private class IrcListener implements WebSocket.Listener
	{
		private final String channel;
		private final String nick;
		private final String oauthAccessToken;
		private final StringBuilder frameBuffer = new StringBuilder();

		IrcListener(String channel, String nick, String oauthAccessToken)
		{
			this.channel = channel;
			this.nick = nick;
			this.oauthAccessToken = oauthAccessToken;
		}

		@Override
		public void onOpen(WebSocket ws)
		{
			webSocket = ws;

			// Each WebSocket text frame is one IRC command - no trailing CRLF needed.
			// Twitch's chat gateway NAKs the standard IRCv3 "echo-message" capability
			// (confirmed live), so a message you send is never echoed back to you over
			// IRC - the caller is responsible for reflecting a sent message locally.
			boolean authenticated = oauthAccessToken != null && nick != null;
			ws.sendText("CAP REQ :twitch.tv/tags twitch.tv/commands", true);

			if (authenticated)
			{
				ws.sendText("PASS oauth:" + oauthAccessToken, true);
				ws.sendText("NICK " + nick.toLowerCase(), true);
			}
			else
			{
				// Twitch allows read-only IRC access with no OAuth token at all, as long
				// as the nick follows the "justinfanNNNNN" convention reserved for
				// anonymous viewers.
				String anonymousNick = "justinfan" + (10000 + new SecureRandom().nextInt(90000));
				ws.sendText("NICK " + anonymousNick, true);
			}

			ws.sendText("JOIN #" + channel, true);

			WebSocket.Listener.super.onOpen(ws);
		}

		@Override
		public CompletionStage<?> onText(WebSocket ws, CharSequence data, boolean last)
		{
			if (stopRequested)
			{
				// A message can already be in flight when disconnect() runs - drop it
				// rather than keep appending to a feed the user just asked to stop.
				return null;
			}

			frameBuffer.append(data);
			if (last)
			{
				// Twitch can batch several IRC lines into one WebSocket frame, especially
				// during fast chat, so split on CRLF instead of assuming one line/frame.
				String batch = frameBuffer.toString();
				frameBuffer.setLength(0);
				for (String line : batch.split("\r\n"))
				{
					if (!line.isEmpty())
					{
						handleLine(ws, line, channel);
					}
				}
			}
			ws.request(1);
			return null;
		}

		@Override
		public void onError(WebSocket ws, Throwable error)
		{
			if (!stopRequested)
			{
				listener.onDisconnected("Connection error: " + rootMessage(error));
			}
		}

		@Override
		public CompletionStage<?> onClose(WebSocket ws, int statusCode, String reason)
		{
			if (!stopRequested)
			{
				listener.onDisconnected(reason == null || reason.isEmpty() ? "Connection closed by Twitch" : reason);
			}
			return null;
		}
	}

	private void handleLine(WebSocket ws, String line, String channel)
	{
		if (line.startsWith("PING"))
		{
			ws.sendText("PONG :tmi.twitch.tv", true);
			return;
		}

		if (line.contains("NOTICE") && (line.contains("Login authentication failed") || line.contains("Improperly formatted auth")))
		{
			listener.onDisconnected("Twitch rejected the login - try logging in again");
			return;
		}

		if (line.contains(" 001 ") || line.contains("JOIN #" + channel))
		{
			listener.onConnected(channel);
			return;
		}

		if (line.contains("PRIVMSG #" + channel))
		{
			TwitchMessage message = parsePrivmsg(line);
			if (message != null)
			{
				listener.onMessage(message);
			}
			return;
		}

		if (line.contains("USERSTATE #" + channel))
		{
			Map<String, String> tags = parseTags(line);
			listener.onSelfUserState(parseColor(tags.get("color")), parseBadges(tags.get("badges")));
			return;
		}

		if (line.contains("USERNOTICE #" + channel))
		{
			TwitchSubEvent event = parseUserNotice(line);
			if (event != null)
			{
				listener.onSubEvent(event);
			}
		}
	}

	/**
	 * Parses a sub/resub/gift-sub {@code USERNOTICE}. Twitch also sends USERNOTICE for
	 * raids, rituals, and bits-badge unlocks, none of which carry the tags this looks
	 * for, so those fall through and return {@code null} - not an error, just an event
	 * type this plugin doesn't currently show.
	 */
	TwitchSubEvent parseUserNotice(String line)
	{
		Map<String, String> tags = parseTags(line);
		String msgId = tags.get("msg-id");
		if (msgId == null)
		{
			return null;
		}

		long now = System.currentTimeMillis();
		switch (msgId)
		{
			case "sub":
			case "resub":
			{
				String displayName = tags.get("display-name");
				if (displayName == null || displayName.isEmpty())
				{
					return null;
				}
				return new TwitchSubEvent(TwitchSubEvent.Type.SUB, displayName, 1, now);
			}
			case "subgift":
			case "anonsubgift":
			{
				String recipient = tags.get("msg-param-recipient-display-name");
				if (recipient == null || recipient.isEmpty())
				{
					return null;
				}
				return new TwitchSubEvent(TwitchSubEvent.Type.GIFT_SUB, recipient, 1, now);
			}
			case "submysterygift":
			case "anonsubmysterygift":
			{
				String gifter = tags.get("display-name");
				if (gifter == null || gifter.isEmpty())
				{
					gifter = "An anonymous gifter";
				}
				int count = parsePositiveInt(tags.get("msg-param-mass-gift-count"), 1);
				return new TwitchSubEvent(TwitchSubEvent.Type.GIFT_BOMB, gifter, count, now);
			}
			default:
				return null;
		}
	}

	private static int parsePositiveInt(String value, int fallback)
	{
		if (value == null)
		{
			return fallback;
		}
		try
		{
			int parsed = Integer.parseInt(value);
			return parsed > 0 ? parsed : fallback;
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}

	/**
	 * Parses the {@code @key=value;key=value ...} IRCv3 tag prefix off the front of a
	 * line, if present. Returns an empty map for a line with no tags.
	 */
	private Map<String, String> parseTags(String line)
	{
		Map<String, String> tags = new HashMap<>();
		if (!line.startsWith("@"))
		{
			return tags;
		}

		int spaceIndex = line.indexOf(' ');
		if (spaceIndex < 0)
		{
			return tags;
		}

		for (String tag : line.substring(1, spaceIndex).split(";"))
		{
			int eq = tag.indexOf('=');
			if (eq > 0)
			{
				tags.put(tag.substring(0, eq), tag.substring(eq + 1));
			}
		}
		return tags;
	}

	/**
	 * Parses a single IRCv3-tagged PRIVMSG line, e.g.:
	 * {@code @color=#FF0000;display-name=SomeUser;... :someuser!someuser@someuser.tmi.twitch.tv PRIVMSG #channel :hello}
	 */
	private TwitchMessage parsePrivmsg(String line)
	{
		Map<String, String> tags = parseTags(line);
		String rest = line.startsWith("@") ? line.substring(line.indexOf(' ') + 1) : line;

		int privmsgIndex = rest.indexOf("PRIVMSG");
		int messageStart = rest.indexOf(" :", privmsgIndex);
		if (privmsgIndex < 0 || messageStart < 0)
		{
			return null;
		}

		String body = rest.substring(messageStart + 2);

		String displayName = tags.get("display-name");
		if (displayName == null || displayName.isEmpty())
		{
			// Fall back to the IRC nick out of "prefix!user@host PRIVMSG ..." when a viewer
			// has never set a display name (rare, but happens for very old accounts).
			displayName = extractNickFromPrefix(rest.substring(0, privmsgIndex));
		}

		Color color = parseColor(tags.get("color"));
		List<TwitchMessage.BadgeRef> badges = parseBadges(tags.get("badges"));

		return new TwitchMessage(displayName, body, color, System.currentTimeMillis(), badges);
	}

	/**
	 * Parses the {@code badges} tag, e.g. {@code subscriber/12,moderator/1}.
	 */
	private List<TwitchMessage.BadgeRef> parseBadges(String raw)
	{
		List<TwitchMessage.BadgeRef> badges = new ArrayList<>();
		if (raw == null || raw.isEmpty())
		{
			return badges;
		}
		for (String entry : raw.split(","))
		{
			int slash = entry.indexOf('/');
			if (slash > 0)
			{
				badges.add(new TwitchMessage.BadgeRef(entry.substring(0, slash), entry.substring(slash + 1)));
			}
		}
		return badges;
	}

	private String extractNickFromPrefix(String prefixSection)
	{
		String trimmed = prefixSection.trim();
		if (trimmed.startsWith(":"))
		{
			trimmed = trimmed.substring(1);
		}
		int bang = trimmed.indexOf('!');
		return bang > 0 ? trimmed.substring(0, bang) : trimmed;
	}

	private Color parseColor(String hex)
	{
		if (hex == null || hex.isEmpty())
		{
			return null;
		}
		try
		{
			return Color.decode(hex);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static String rootMessage(Throwable error)
	{
		Throwable cause = error;
		while (cause.getCause() != null)
		{
			cause = cause.getCause();
		}
		String message = cause.getMessage();
		return message != null ? message : cause.getClass().getSimpleName();
	}

	private static String normalizeChannel(String channel)
	{
		String trimmed = channel.trim().toLowerCase();
		return trimmed.startsWith("#") ? trimmed.substring(1) : trimmed;
	}
}

package com.twitchsidepanel.twitch;

import java.awt.Color;
import java.util.List;

/**
 * Callbacks fired by {@link TwitchChatClient}. All callbacks arrive on the client's own
 * background thread, not the Swing EDT - implementations that touch UI must hop over via
 * SwingUtilities.invokeLater themselves.
 */
public interface TwitchChatListener
{
	void onConnected(String channel);

	void onDisconnected(String reason);

	void onMessage(TwitchMessage message);

	/**
	 * Twitch sends this on an authenticated connection (on join, and again after each
	 * message you send) with your own display color and badges in the channel. There is
	 * no default implementation needed for anonymous connections, which never receive it.
	 */
	default void onSelfUserState(Color color, List<TwitchMessage.BadgeRef> badges)
	{
	}

	/**
	 * A subscription or gift-sub happened in the channel. Arrives on any connection
	 * (anonymous or authenticated) - Twitch broadcasts these to every viewer, the same
	 * as chat messages.
	 */
	default void onSubEvent(TwitchSubEvent event)
	{
	}
}

package com.twitchsidepanel.twitch;

import java.awt.Color;
import java.util.Collections;
import java.util.List;

/**
 * A single parsed Twitch PRIVMSG, ready for display.
 */
public class TwitchMessage
{
	public final String displayName;
	public final String body;
	public final Color color;
	public final long receivedAtMillis;
	public final List<BadgeRef> badges;

	public TwitchMessage(String displayName, String body, Color color, long receivedAtMillis,
		List<BadgeRef> badges)
	{
		this.displayName = displayName;
		this.body = body;
		this.color = color;
		this.receivedAtMillis = receivedAtMillis;
		this.badges = badges == null ? Collections.emptyList() : badges;
	}

	/**
	 * One badge from the IRC {@code badges} tag, e.g. {@code subscriber/12}.
	 */
	public static class BadgeRef
	{
		public final String setId;
		public final String version;

		public BadgeRef(String setId, String version)
		{
			this.setId = setId;
			this.version = version;
		}
	}
}

package com.twitchsidepanel.twitch;

/**
 * A subscription or gift-sub event parsed from a Twitch IRC {@code USERNOTICE}. Twitch
 * sends these on the same chat connection as regular messages - no separate EventSub
 * infrastructure needed to know about them.
 */
public class TwitchSubEvent
{
	public enum Type
	{
		/** A new or repeat ("resub") subscription, paid for by the subscriber themselves. */
		SUB,
		/** A single gift sub - {@link #displayName} is the recipient. */
		GIFT_SUB,
		/** A batch of gift subs from one gifter - {@link #displayName} is the gifter. */
		GIFT_BOMB
	}

	public final Type type;
	public final String displayName;
	/** Number of subs gifted at once, for {@link Type#GIFT_BOMB}; meaningless otherwise. */
	public final int count;
	public final long receivedAtMillis;

	public TwitchSubEvent(Type type, String displayName, int count, long receivedAtMillis)
	{
		this.type = type;
		this.displayName = displayName;
		this.count = count;
		this.receivedAtMillis = receivedAtMillis;
	}
}

